// client-ordering · кейсы co-08, co-10, co-11, co-12, co-17 п.3 (.qa/tests/client-ordering/) — עגלה וביצוע הזמנה
// #6fcb020f: счётчик корзины считает строки — 1 строка «פריט אחד», 2 строки «2 פריטים» (раньше «1 פריטים»).
// Корзина buyer хранится на сервере и общая для всех прогонов → только @desktop и serial; в конце корзина пустая.
// ⚠️ НЕ запускать параллельно с orders/order-lifecycle, inventory/inventory-lifecycle, picking/picking-flow,
//    customers-pricing/pricing-lifecycle (общая корзина buyer).
// #a5f94502 (офлайн): повторная отправка создаёт заказ «QA-AUTO-client-ordering-offline-…» → afterAll отклоняет его под admin.
import { test, expect, Page, Browser } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/buyer.json') });
test.describe.configure({ mode: 'serial' });

const ITEM = { id: '340b7b2b-e022-4f3b-a6f0-f9a3dc8ecfe8', name: 'מצית קליפט' }; // в наличии, ₪5.00 у buyer

async function emptyCart(page: Page) {
  await page.goto('/shop/cart');
  await expect(page.getByRole('heading', { name: 'העגלה שלי' })).toBeVisible();
  const remove = page.getByRole('button', { name: /^הסרה מהעגלה/ });
  // ждём, пока корзина загрузится (staging бывает медленным): либо есть позиции, либо «העגלה ריקה»
  await expect(remove.first().or(page.getByText('העגלה ריקה'))).toBeVisible({ timeout: 20_000 });
  while (await remove.count()) {
    await remove.first().click();
    await page.waitForTimeout(500);
  }
  await expect(page.getByText('העגלה ריקה')).toBeVisible();
}

async function addItem(page: Page) {
  await page.goto(`/shop/p/${ITEM.id}`);
  const added = page.waitForResponse(r => r.url().includes('cart_set_item'));
  await page.getByRole('button', { name: /^הוסף לעגלה/ }).click();
  await added;
  await page.goto('/shop/cart');
  await expect(page.getByText(ITEM.name, { exact: true })).toBeVisible();
  await expect(page.getByText('פריט אחד', { exact: true }).first()).toBeVisible();
}

const summary = (page: Page) => page.getByText('סה״כ משוער').locator('..');
const OFFLINE_MSG = 'אין חיבור לרשת. העגלה נשמרה — אפשר לנסות לשלוח שוב כשהחיבור יחזור.';
let offlineOrderNo = ''; // «#N» заказа из офлайн-теста — отклоняется в afterAll

async function topOrderNo(page: Page) {
  await page.goto('/shop/orders');
  const first = page.getByRole('link', { name: /^הזמנה #\d+/ }).first();
  await expect(first).toBeVisible({ timeout: 20_000 });
  return (await first.innerText()).match(/#\d+/)![0];
}

async function adminReject(browser: Browser, orderNo: string) {
  const ctx = await browser.newContext({ storageState: path.resolve(__dirname, '../../../auth/admin.json'), locale: 'he-IL' });
  const page = await ctx.newPage();
  try {
    await page.goto('/orders');
    await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
    await page.getByRole('button', { name: new RegExp(`^${orderNo} `) }).click();
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה ${orderNo}` })).toBeVisible({ timeout: 20_000 });
    const reject = page.getByRole('button', { name: 'דחייה' });
    if (!(await reject.count())) return; // уже не «ממתין לאישור»
    await reject.click();
    const dlg = page.getByRole('dialog');
    await dlg.getByRole('textbox', { name: 'סיבת הדחייה *' }).fill('QA-AUTO cleanup #a5f94502');
    await dlg.getByRole('button', { name: 'דחה הזמנה' }).click();
    await expect(page.getByRole('heading', { level: 1 }).locator('..')).toContainText('נדחתה', { timeout: 20_000 });
  } finally {
    await ctx.close();
  }
}

test.describe('client-ordering — עגלה וביצוע הזמנה', () => {
  test.beforeEach(async ({ page }) => { await emptyCart(page); });
  test.afterAll(async ({ browser }) => {
    test.setTimeout(120_000);
    const ctx = await browser.newContext({ storageState: path.resolve(__dirname, '../../../auth/buyer.json') });
    await emptyCart(await ctx.newPage());
    await ctx.close();
    if (offlineOrderNo) await adminReject(browser, offlineOrderNo);
  });

  test('עגלה: הוספה במחיר הלקוח, שינוי כמות מעדכן סכום, הסרה → מצב ריק #6a38cf5f #6fcb020f @desktop @prod-safe', async ({ page }) => {
    await page.goto('/shop');
    await page.getByRole('searchbox', { name: 'חיפוש מוצר' }).fill(ITEM.name);
    await page.getByRole('button', { name: `הוספה לעגלה — ${ITEM.name}` }).click();
    await expect(page.getByRole('link', { name: 'עגלה — פריט אחד' })).toBeVisible();

    await page.getByRole('link', { name: 'עגלה — פריט אחד' }).click();
    await expect(page).toHaveURL(/\/shop\/cart/);
    await expect(page.getByText('פריט אחד', { exact: true }).first()).toBeVisible();
    await expect(page.getByText('1 פריטים')).toHaveCount(0);
    await expect(page.getByText(ITEM.name, { exact: true })).toBeVisible();
    await expect(summary(page)).toContainText('₪5.00');
    await expect(page.getByText('מחיר משוער לפי המחירון שלך — כפוף לאישור המפיץ')).toBeVisible();
    const minus = page.getByRole('button', { name: `הפחתת יחידה — ${ITEM.name}` });
    await expect(minus).toBeDisabled();

    const plus = page.getByRole('button', { name: `הוספת יחידה — ${ITEM.name}` });
    await plus.click();
    await expect(summary(page)).toContainText('₪10.00');
    await plus.click();
    await expect(summary(page)).toContainText('₪15.00');
    await minus.click();
    await expect(summary(page)).toContainText('₪10.00');

    await page.getByRole('button', { name: `הסרה מהעגלה — ${ITEM.name}` }).click();
    await expect(page.getByText('העגלה ריקה')).toBeVisible();
    await expect(page.getByText('0 פריטים')).toBeVisible();
    await expect(page.getByText('עדיין לא הוספת מוצרים. חזור לקטלוג כדי להתחיל הזמנה.')).toBeVisible();
    await page.getByRole('button', { name: 'חזרה לקטלוג' }).last().click();
    await expect(page).toHaveURL(/\/shop\/?$/);
  });

  test('מונה העגלה סופר שורות: שורה אחת (גם בכמות 2) — «פריט אחד», שתי שורות — «2 פריטים» #6fcb020f @desktop @prod-safe', async ({ page }) => {
    await addItem(page); // 1 строка, 1 шт. → «פריט אחד»
    const plus = page.getByRole('button', { name: `הוספת יחידה — ${ITEM.name}` });
    await plus.click();
    await expect(summary(page)).toContainText('₪10.00');
    await expect(page.getByText('פריט אחד', { exact: true }).first()).toBeVisible(); // 2 шт. в одной строке — всё ещё одна позиция
    await expect(page.getByText('2 פריטים', { exact: true })).toHaveCount(0);

    // вторая строка — любой товар из «השלימו את ההזמנה»
    const suggestion = page.getByRole('button', { name: /^הוספה לעגלה — / }).first();
    await expect(suggestion).toBeVisible({ timeout: 20_000 });
    const added = page.waitForResponse((r) => r.url().includes('cart_set_item'));
    await suggestion.click();
    await added;
    await expect(page.getByRole('button', { name: /^הסרה מהעגלה/ })).toHaveCount(2, { timeout: 15_000 });
    await expect(page.getByText('2 פריטים', { exact: true }).first()).toBeVisible();
    await expect(page.getByText('פריט אחד', { exact: true })).toHaveCount(0);
    // очистка — beforeEach/afterAll (emptyCart)
  });

  test('«המשך לביצוע הזמנה» פעיל כשהמוצר במלאי; עגלה ריקה → שליחה חסומה עם הודעה #6a72f806 #6a38cf5f @desktop @prod-safe', async ({ page }) => {
    await addItem(page);
    await page.goto('/shop/cart');
    const next = page.getByRole('button', { name: 'המשך לביצוע הזמנה' });
    await expect(next).toBeEnabled();
    await next.click();
    await expect(page).toHaveURL(/\/shop\/checkout/);
    await expect(page.getByRole('heading', { name: 'ביצוע הזמנה' })).toBeVisible();
    await expect(page.getByRole('heading', { name: 'משלוח אל' })).toBeVisible();
    await expect(page.getByRole('textbox', { name: 'הערות להזמנה' })).toBeVisible();
    await expect(page.getByText('סה״כ לתשלום')).toBeVisible();
    await expect(page.getByRole('button', { name: 'שליחת הזמנה' })).toBeEnabled();

    await emptyCart(page);
    await page.goto('/shop/checkout');
    await expect(page.getByRole('alert')).toHaveText('העגלה ריקה — לא ניתן לשלוח הזמנה. חזור לקטלוג והוסף מוצרים.');
    await expect(page.getByRole('button', { name: 'שליחת הזמנה' })).toBeDisabled();
  });

  test('כשל בשליחת הזמנה → שגיאה, העגלה נשמרת לניסיון חוזר #6a38cf5f @desktop @prod-safe', async ({ page }) => {
    await addItem(page);
    await page.route('**/rest/v1/rpc/place_order', (route) =>
      route.fulfill({ status: 503, contentType: 'application/json', body: '{"message":"QA simulated outage"}' }));
    await page.goto('/shop/checkout');
    await page.getByRole('textbox', { name: 'הערות להזמנה' }).fill('QA-AUTO-client-ordering-fail');
    await page.getByRole('button', { name: 'שליחת הזמנה' }).click();
    await expect(page.getByRole('alert')).toHaveText('שליחת ההזמנה נכשלה. העגלה נשמרה — אפשר לנסות שוב.');
    await expect(page).toHaveURL(/\/shop\/checkout/);
    await expect(page.getByText('פריטים בעגלה').locator('..')).toContainText('1');
    await expect(page.getByRole('button', { name: 'שליחת הזמנה' })).toBeEnabled();
    await page.unroute('**/rest/v1/rpc/place_order');
  });

  test('אין רשת: הודעה מיידית, הכפתור פעיל, העגלה נשמרת; אחרי חזרת הרשת אין הזמנה אוטומטית; שליחה חוזרת — הזמנה אחת #a5f94502 #6a38cf5f @desktop', async ({ page, context }) => {
    test.setTimeout(180_000);
    const note = `QA-AUTO-client-ordering-offline-${Date.now()}`;
    const before = await topOrderNo(page);
    await addItem(page);
    await page.goto('/shop/checkout');
    await page.getByRole('textbox', { name: 'הערות להזמנה' }).fill(note);
    const send = page.getByRole('button', { name: 'שליחת הזמנה' });

    await context.setOffline(true);
    const t0 = Date.now();
    await send.click();
    await expect(page.getByText(OFFLINE_MSG)).toBeVisible({ timeout: 5_000 });
    expect(Date.now() - t0, 'ошибка сразу, без зависания «שולח…»').toBeLessThan(5_000);
    await expect(send).toBeEnabled();
    await expect(page.getByText('שולח…')).toHaveCount(0);
    await expect(page).toHaveURL(/\/shop\/checkout/);
    await expect(page.getByText('פריטים בעגלה').locator('..')).toContainText('1');

    // сеть вернулась: заказ сам НЕ отправляется (наблюдаем 60 с — так проверялось вручную)
    await context.setOffline(false);
    await page.waitForTimeout(60_000);
    await expect(page.getByRole('heading', { name: 'ההזמנה נקלטה!' })).toHaveCount(0);
    const check = await context.newPage();
    expect(await topOrderNo(check), 'после возврата сети новый заказ не появился').toBe(before);
    await check.close();

    // повторное нажатие — ровно один новый заказ
    await send.click();
    await expect(page.getByRole('heading', { name: 'ההזמנה נקלטה!' })).toBeVisible({ timeout: 20_000 });
    offlineOrderNo = (await page.getByText(/^הזמנה\s*#\d+/).first().innerText()).match(/#\d+/)![0];
    expect(Number(offlineOrderNo.slice(1))).toBeGreaterThan(Number(before.slice(1)));
    const list = await context.newPage();
    await list.goto('/shop/orders');
    const rows = list.getByRole('link', { name: /^הזמנה #\d+/ });
    await expect(rows.first()).toContainText(offlineOrderNo);
    await expect(rows.nth(1)).toContainText(before); // между ними нет лишних (дублей)
    await list.close();
  });

  test('ביצוע הזמנה: «ההזמנה נקלטה!» עם מספר, ההערה נשמרת, העגלה מתרוקנת #6a38cf5f @desktop', async ({ page }) => {
    // Создаёт настоящий заказ на staging (статус «ממתינה לאישור»), оплата не проводится.
    const note = `QA-AUTO-client-ordering-e2e-${Date.now()}`;
    await addItem(page);
    await page.goto('/shop/cart');
    await page.getByRole('button', { name: `הוספת יחידה — ${ITEM.name}` }).click();
    await expect(summary(page)).toContainText('₪10.00');
    await page.getByRole('button', { name: 'המשך לביצוע הזמנה' }).click();
    await page.getByRole('textbox', { name: 'הערות להזמנה' }).fill(note);
    await page.getByRole('button', { name: 'שליחת הזמנה' }).click();

    await expect(page.getByRole('heading', { name: 'ההזמנה נקלטה!' })).toBeVisible({ timeout: 20_000 });
    await expect(page).toHaveURL(/\/shop\/order\/[0-9a-f-]{36}/);
    const confirm = page.getByText(/^הזמנה\s*#\d+/).first();
    await expect(confirm).toContainText('₪10.00');
    const orderNo = (await confirm.innerText()).match(/#\d+/)![0];
    await expect(page.getByText(/נשלחה למפיץ/)).toBeVisible();

    await page.getByRole('button', { name: 'צפייה בהזמנות שלי' }).click();
    await expect(page).toHaveURL(/\/shop\/orders/);
    const row = page.getByRole('link', { name: new RegExp(`הזמנה ${orderNo}\\b`) });
    await expect(row).toContainText('ממתינה לאישור');
    await row.click();
    await expect(page.getByRole('heading', { level: 1, name: `הזמנה ${orderNo}` })).toBeVisible();
    await expect(page.getByText(`${ITEM.name}`, { exact: true })).toBeVisible();
    await expect(page.getByText('2 × ₪5.00')).toBeVisible();
    await expect(page.getByRole('heading', { name: 'הערות להזמנה' })).toBeVisible();
    await expect(page.getByText(note)).toBeVisible();

    await page.goto('/shop/cart');
    await expect(page.getByText('העגלה ריקה')).toBeVisible();
  });
});
